export function carBrandLogo(brand) { const src = carBrandLogos[brand]; return src ? `<img class="car-brand-logo" src="${src}" alt="" aria-hidden="true" width="64" height="48">` : ''; }

export const escapeHtml = value => String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#39;');
export const formatMoney = value => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value);
export const formatNumber = value => new Intl.NumberFormat('id-ID').format(value);
const iconPaths = {
  arrow: '<path d="M7 17 17 7M7 7h10v10"/>', right: '<path d="m9 5 7 7-7 7"/>', left: '<path d="m15 5-7 7 7 7"/>', down: '<path d="m6 9 6 6 6-6"/>',
  search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>', close: '<path d="m6 6 12 12M6 18 18 6"/>',
  heart: '<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
  filter: '<path d="M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6m-7 0v6"/>', pin: '<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
  car: '<path d="m5 7 2-4h10l2 4 2 3v8H3v-8zM3 10h18M6 14h2m8 0h2M5 18v3m14-3v3"/>', grid: '<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  list: '<path d="M9 5h12M9 12h12M9 19h12M3 5h1M3 12h1M3 19h1"/>', menu: '<path d="M3 6h18M3 12h18M3 18h18"/>', pause: '<path d="M8 5v14M16 5v14"/>', play: '<path d="m8 4 12 8-12 8Z"/>',
  message: '<path d="M21 11.5a8.5 8.5 0 0 1-12.6 7.4L3 21l2.1-5.4A8.5 8.5 0 1 1 21 11.5Z"/><path d="M8 9h8m-8 4h5"/>', check: '<path d="m5 12 4 4L19 6"/>', photo: '<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8" cy="9" r="1.5"/><path d="m21 16-5-5L5 20"/>', plus: '<path d="M12 5v14M5 12h14"/>',
};
export function icon(name, size = 18) { return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name] || iconPaths.car}</svg>`; }
export function imageMarkup(src, alt, options = {}) {
  const safe = /^https:\/\//.test(src || '') || /^\/(?!\/)/.test(src || '') ? src : '/car-placeholder.svg';
  let srcset = '';
  if (safe.startsWith('https://images.unsplash.com/')) { try { const small = new URL(safe), large = new URL(safe); small.searchParams.set('w', '480'); large.searchParams.set('w', options.hero ? '1600' : '900'); srcset = ` srcset="${escapeHtml(small.href)} 480w, ${escapeHtml(large.href)} ${options.hero ? 1600 : 900}w" sizes="${options.hero ? '(max-width: 760px) 100vw, 65vw' : '(max-width: 600px) 100vw, (max-width: 1100px) 45vw, 28vw'}"`; } catch {} }
  return `<span class="photo-frame ${options.className || ''}"><img src="${escapeHtml(safe)}" alt="${escapeHtml(alt)}" width="900" height="600" loading="${options.hero ? 'eager' : 'lazy'}" decoding="async"${options.hero ? ' fetchpriority="high"' : ''}${srcset}></span>`;
}
export function brandMarkup(settings) { return `<a class="brand" href="#" aria-label="${escapeHtml(settings.name)}, beranda">${settings.logo ? `<img src="${escapeHtml(settings.logo)}" alt="">` : '<span class="brand-mark" aria-hidden="true">b<span>.</span></span>'}<span class="brand-name">${escapeHtml(settings.name)}<small>Mobil bekas pilihan</small></span></a>`; }
function checkList(cars, key, field, values) { return values.map(value => `<label class="filter-check"><input type="checkbox" data-filter="${key}" value="${escapeHtml(value)}"><span>${escapeHtml(value)}</span><small>${cars.filter(c => (c[field] || 'Lainnya') === value).length}</small></label>`).join(''); }
export function modelListMarkup(cars, selectedBrands = []) { const pool = selectedBrands.length ? cars.filter(c => selectedBrands.includes(c.brand)) : cars; return checkList(cars, 'models', 'name', [...new Set(pool.map(c => c.name))].sort()); }
export function filterPanelMarkup(cars, scope = 'desktop') {
  const values = field => [...new Set(cars.map(c => c[field] || 'Lainnya'))].sort();
  const yearOptions = Array.from({ length: new Date().getFullYear() - 1994 }, (_, i) => new Date().getFullYear() - i).map(y => `<option value="${y}">${y}</option>`).join('');
  const group = (title, body, open = false) => `<details class="filter-group"${open ? ' open' : ''}><summary>${title}${icon('plus', 16)}</summary><div class="filter-group-body">${body}</div></details>`;
  return `<div class="filter-panel" data-filter-panel="${scope}"><div class="filter-heading"><h2>${icon('filter')} Filter mobil</h2><button class="text-btn" data-reset>Reset</button></div>
    ${group('Harga', `<div class="range-inputs"><label>Minimum (juta)<input type="number" inputmode="numeric" min="0" max="100000" data-filter="priceMin" placeholder="0"></label><span>–</span><label>Maksimum (juta)<input type="number" inputmode="numeric" min="0" max="100000" data-filter="priceMax" placeholder="Semua"></label></div><label class="price-slider-label">Batas harga maksimum <output data-price-label>Semua harga</output><input type="range" min="0" max="1000" step="10" value="1000" data-price-slider aria-label="Batas harga maksimum dalam juta rupiah"></label><div class="price-presets">${[['0', '200', '< 200 juta'], ['200', '300', '200–300 juta'], ['300', '500', '300–500 juta'], ['500', '', '> 500 juta']].map(([min, max, label]) => `<button type="button" data-price-min="${min}" data-price-max="${max}">${label}</button>`).join('')}</div><p class="filter-range-error" data-price-error role="status" hidden>Harga minimum melebihi maksimum.</p>`, true)}
    ${group('Merek & model', `<label class="brand-search">${icon('search', 15)}<input type="search" placeholder="Cari merek" data-brand-search aria-label="Cari merek dalam filter"></label><div class="filter-options brand-options">${checkList(cars, 'brands', 'brand', values('brand'))}</div><details class="model-group"><summary>Pilih model / tipe ${icon('down', 14)}</summary><div class="filter-options" data-model-list>${modelListMarkup(cars)}</div></details>`, true)}
    ${group('Tahun', `<div class="range-inputs"><label>Dari<select data-filter="yearMin"><option value="">Semua</option>${yearOptions}</select></label><span>–</span><label>Sampai<select data-filter="yearMax"><option value="">Semua</option>${yearOptions}</select></label></div><p class="filter-range-error" data-year-error role="status" hidden>Tahun awal melebihi tahun akhir.</p>`, true)}
    ${group('Transmisi', checkList(cars, 'transmissions', 'transmission', values('transmission')), true)}
    ${group('Kilometer', `<label class="single-field">Jarak tempuh maksimum<select data-filter="mileageMax"><option value="">Semua kilometer</option>${[10000, 30000, 50000, 75000, 100000, 150000].map(n => `<option value="${n}">Hingga ${formatNumber(n)} km</option>`).join('')}</select></label>`)}
    ${group('Bahan bakar', checkList(cars, 'fuels', 'fuel', values('fuel')))}
    ${group('Tipe bodi', `<div class="body-options">${values('bodyType').map(value => `<label class="body-option"><input type="checkbox" data-filter="bodyTypes" value="${escapeHtml(value)}">${icon('car', 28)}<span>${escapeHtml(value)}</span></label>`).join('')}</div>`)}
    ${group('Lokasi', checkList(cars, 'locations', 'location', values('location')))}
  </div>`;
}
export function cardsMarkup(cars, saved = []) {
  return cars.map((c, index) => `<article class="car-card reveal" style="--reveal-delay:${(index % 3) * 45}ms" data-car-id="${escapeHtml(c.id)}"><div class="car-image"><button class="photo-link" data-detail="${escapeHtml(c.id)}" aria-label="Lihat ${escapeHtml(c.brand + ' ' + c.name)}">${imageMarkup(c.photos[0], c.demo ? `Ilustrasi ${c.brand} ${c.name}, bukan foto unit asli` : `${c.brand} ${c.name}`)}</button><span class="status status-${c.status.toLowerCase()}"><i></i>${escapeHtml(c.status)}</span><button class="save-car${saved.includes(c.id) ? ' saved' : ''}" data-save="${escapeHtml(c.id)}" aria-label="${saved.includes(c.id) ? 'Hapus dari disimpan' : 'Simpan mobil'} ${escapeHtml(c.brand + ' ' + c.name)}" aria-pressed="${saved.includes(c.id)}">${icon('heart')}</button><span class="photo-counter">${icon('photo', 13)} ${c.demo ? 'Ilustrasi' : c.photos.length + ' foto'}</span><span class="card-photo-hint">Lihat galeri ${icon('arrow', 15)}</span></div><div class="car-content"><div class="car-meta-top"><span class="card-brand-label">${carBrandLogo(c.brand)}${escapeHtml(c.brand)}</span><span>${escapeHtml(c.bodyType || '')}</span></div><h3><button data-detail="${escapeHtml(c.id)}">${escapeHtml(c.name)}</button></h3><div class="specs"><span>${c.year}</span><i></i><span>${formatNumber(c.mileage)} km</span><i></i><span>${escapeHtml(c.transmission)}</span></div><div class="car-price"><strong>${formatMoney(c.price)}</strong><span>${c.demo ? 'Harga ilustrasi' : 'Harga penawaran'}</span></div><div class="car-bottom"><span>${icon('pin', 14)}${escapeHtml(c.location)}</span><button data-detail="${escapeHtml(c.id)}" aria-label="Detail ${escapeHtml(c.brand + ' ' + c.name)}">Detail ${icon('arrow', 17)}</button></div></div></article>`).join('');
}
export function detailMarkup(c) { return `<div class="detail-grid"><div class="detail-gallery"><div data-detail-photo>${imageMarkup(c.photos[0], c.demo ? 'Foto ilustrasi, bukan unit asli' : c.brand + ' ' + c.name)}</div><div class="gallery-controls"><button class="icon-btn" data-gallery-step="-1" aria-label="Foto sebelumnya">${icon('left')}</button><span data-gallery-count>1 / ${c.photos.length}</span><button class="icon-btn" data-gallery-step="1" aria-label="Foto berikutnya">${icon('right')}</button></div><div class="gallery-thumbs">${c.photos.map((src, i) => `<button data-gallery-index="${i}" class="${i === 0 ? 'active' : ''}" aria-label="Foto ${i + 1}" aria-pressed="${i === 0}">${imageMarkup(src, '')}</button>`).join('')}</div>${c.demo ? '<p class="illustration-caption">Foto dan spesifikasi ilustrasi, bukan penawaran unit asli.</p>' : ''}</div><div class="detail-content"><span class="status inline status-${c.status.toLowerCase()}">${escapeHtml(c.status)}</span><p class="car-brand">${escapeHtml(c.brand)}</p><h2 id="detail-title">${escapeHtml(c.name)}</h2><strong class="detail-price">${formatMoney(c.price)}</strong><dl class="detail-specs">${[['Tahun', c.year], ['Kilometer', formatNumber(c.mileage) + ' km'], ['Transmisi', c.transmission], ['Bahan bakar', c.fuel], ['Warna', c.color], ['Tipe bodi', c.bodyType || 'Belum diisi'], ['Lokasi', c.location]].map(([k, v]) => `<div><dt>${escapeHtml(k)}</dt><dd>${escapeHtml(v)}</dd></div>`).join('')}</dl><div class="car-tags">${c.highlights.map(h => `<span>${escapeHtml(h)}</span>`).join('')}</div><h3>Catatan unit</h3><p class="description">${escapeHtml(c.description)}</p><button class="btn primary full" data-contact-car="${escapeHtml(c.id)}"${c.status === 'Terjual' ? ' disabled' : ''}>${icon('message')}${c.status === 'Terjual' ? 'Mobil sudah terjual' : 'Tanya unit via WhatsApp'}</button></div></div>`; }
export function renderShowroom({ cars, settings, storageError = false, preview = false }) {
  const slides = settings.slides, s = slides[0];
  const brands = [...new Set(cars.map(c => c.brand))];
  return `<a class="skip-link" href="#katalog">Langsung ke katalog</a>${preview ? '<div class="preview-note">Pratinjau desain · Semua unit, foto, harga, dan lokasi adalah contoh</div>' : ''}<header class="site-header"><div class="container nav">${brandMarkup(settings)}<nav class="nav-links" aria-label="Navigasi utama"><a class="active" href="#katalog">Koleksi mobil</a><a href="#cara-beli">Cara membeli</a><a href="#tentang">Showroom kami</a></nav><div class="nav-actions"><button class="icon-btn nav-saved" data-saved-view aria-label="Lihat mobil disimpan">${icon('heart')}<span data-saved-count>0</span></button><button class="btn primary nav-contact" data-contact>Hubungi kami ${icon('arrow', 16)}</button><button class="icon-btn mobile-toggle" data-menu aria-label="Buka navigasi" aria-expanded="false">${icon('menu', 22)}</button></div></div></header>
  <main><section class="hero" aria-roledescription="carousel" aria-label="Pilihan mobil"><div class="hero-copy"><div class="hero-intro">${icon('car', 18)} Pilihan mobil. Langkah baru.</div><h1 data-hero-title>${escapeHtml(s.title)}</h1><p data-hero-description>${escapeHtml(s.description)}</p><a href="#katalog" class="btn primary">Jelajahi koleksi ${icon('arrow')}</a><div class="hero-lower"><span>Temukan yang sesuai<br>kebutuhan & anggaran.</span><a href="#katalog" class="hero-scroll" aria-label="Lihat katalog">${icon('down', 22)}</a></div></div><div class="hero-visual"><div class="hero-media" data-hero-media>${imageMarkup(s.image, 'Ilustrasi mobil pilihan showroom', { hero: true })}</div><div class="hero-image-label"><span>${preview || cars.every(c => c.demo) ? 'Foto ilustrasi' : 'Koleksi ' + escapeHtml(settings.name)}</span><span data-slide-count>01 / ${String(slides.length).padStart(2, '0')}</span></div><div class="slide-controls"><button class="hero-icon" data-slide-step="-1" aria-label="Slide sebelumnya">${icon('left')}</button><div class="slide-dots">${slides.map((_, i) => `<button data-slide="${i}" class="${i === 0 ? 'active' : ''}" aria-label="Lihat slide ${i + 1}" aria-current="${i === 0}"><span></span></button>`).join('')}</div><button class="hero-icon" data-slide-step="1" aria-label="Slide berikutnya">${icon('right')}</button><button class="hero-icon" data-pause aria-label="Jeda slideshow" aria-pressed="false">${icon('pause', 16)}</button></div></div></section>
  <div class="brand-strip container"><span>Mulai dari merek favoritmu</span><div>${brands.map(b => `<button data-quick-brand="${escapeHtml(b)}" aria-pressed="false">${carBrandLogo(b)}<span>${escapeHtml(b)}</span><small>${cars.filter(c => c.brand === b).length} mobil</small></button>`).join('')}</div></div>
  <section class="catalog-section container" id="katalog" aria-labelledby="catalog-title"><div class="catalog-heading reveal"><div><p class="breadcrumb">Beranda <span>/</span> Koleksi mobil</p><h2 id="catalog-title">Cari mobil berikutnya.</h2></div><p>Detail jelas. Pilihan lebih mudah.</p></div>${preview || cars.every(c => c.demo) ? `<p class="demo-note">${icon('photo', 14)} Katalog contoh${storageError ? ' · Koneksi penyimpanan belum tersedia' : ''}. Foto dan spesifikasi hanya ilustrasi.</p>` : ''}<div class="catalog-layout"><aside class="desktop-filters" aria-label="Filter katalog">${filterPanelMarkup(cars)}</aside><div class="catalog-results"><form class="catalog-search" role="search"><label class="search-field">${icon('search', 20)}<input type="search" data-query name="q" placeholder="Cari merek, model, atau tipe mobil" aria-label="Cari mobil"></label><button class="btn dark" type="submit">Cari ${icon('right', 16)}</button></form><div class="catalog-toolbar"><div class="status-tabs" role="group" aria-label="Status stok">${[['', 'Semua'], ['Tersedia', 'Tersedia'], ['Dipesan', 'Dipesan'], ['Terjual', 'Terjual']].map(([v, label]) => `<button data-status="${v}" class="${v === '' ? 'active' : ''}" aria-pressed="${v === ''}">${label}</button>`).join('')}</div><button class="btn outline mobile-filter-button" data-open-filters>${icon('filter', 17)} Filter <span data-filter-count>0</span></button><button class="saved-toggle" data-saved-view aria-pressed="false">${icon('heart', 16)} Disimpan</button></div><div class="active-filters" data-active-filters hidden></div><div class="results-row"><p role="status" aria-live="polite" aria-atomic="true" data-results-count><strong>${cars.length}</strong> mobil ditemukan</p><div class="results-options"><label>Urutkan<select data-sort aria-label="Urutkan mobil"><option value="newest">Tahun terbaru</option><option value="oldest">Tahun terlama</option><option value="price-low">Harga terendah</option><option value="price-high">Harga tertinggi</option><option value="mileage">Kilometer terendah</option></select></label><div class="view-switch" role="group" aria-label="Tampilan katalog"><button class="active" data-view="grid" aria-label="Tampilan grid" aria-pressed="true">${icon('grid', 16)}</button><button data-view="list" aria-label="Tampilan daftar" aria-pressed="false">${icon('list', 18)}</button></div></div></div><div class="car-grid" data-car-grid>${cardsMarkup(filterCars(cars, blankFilters()).slice(0, 6))}</div><div class="empty-state" data-empty hidden>${icon('car', 40)}<h3>Belum ada yang cocok.</h3><p>Coba kurangi filter atau gunakan kata pencarian lain.</p><button class="btn outline" data-reset>Reset pencarian</button></div><div class="load-more"><p data-showing>Menampilkan ${Math.min(cars.length, 6)} dari ${cars.length} mobil</p><button class="btn outline" data-load-more${cars.length <= 6 ? ' hidden' : ''}>Tampilkan mobil lainnya ${icon('plus', 16)}</button></div></div></div></section>
  <section class="buy-section" id="cara-beli"><div class="container"><div class="buy-heading reveal"><h2>Dari layar, ke garasimu.</h2><p>Kenali dulu. Lihat langsung. Baru putuskan.</p></div><ol class="buy-steps"><li class="reveal"><span>01</span><div><h3>Temukan pilihanmu</h3><p>Saring koleksi berdasarkan anggaran dan kebutuhan.</p></div></li><li class="reveal"><span>02</span><div><h3>Tanyakan detail unit</h3><p>Hubungi showroom untuk kondisi dan stok terbaru.</p></div></li><li class="reveal"><span>03</span><div><h3>Jadwalkan kunjungan</h3><p>Lihat mobil secara langsung sebelum mengambil keputusan.</p></div></li></ol></div></section><section class="container contact-section reveal" id="tentang"><div><span class="contact-symbol" aria-hidden="true">b.</span><h2>Mobil berikutnya,<br>kita cari bersama.</h2></div><div><h3>${escapeHtml(settings.name)}</h3><p>${escapeHtml(settings.tagline)}</p>${settings.address ? `<p class="address">${icon('pin', 16)}${escapeHtml(settings.address)}</p>` : '<p>Hubungi kami untuk menanyakan unit dan membuat janji kunjungan.</p>'}<button class="btn primary" data-contact>Ngobrol dengan showroom ${icon('arrow', 17)}</button></div></section></main><footer class="footer container">${brandMarkup(settings)}<p>© ${new Date().getFullYear()} ${escapeHtml(settings.name)}</p><a href="/admin"${preview ? ' data-admin-preview' : ''}>Admin showroom ${icon('arrow', 14)}</a></footer>
  <dialog class="filter-drawer" aria-labelledby="filter-drawer-title" data-filter-drawer><div class="drawer-top"><h2 id="filter-drawer-title">Sesuaikan pilihanmu</h2><button class="icon-btn" data-close-filters aria-label="Tutup filter">${icon('close', 23)}</button></div><div class="drawer-scroll">${filterPanelMarkup(cars, 'mobile')}</div><div class="drawer-footer"><button class="text-btn" data-reset-draft>Reset</button><button class="btn primary" data-apply-filters>Tampilkan ${cars.length} mobil ${icon('right', 17)}</button></div></dialog><dialog class="detail-dialog" data-detail-dialog aria-labelledby="detail-title"><button class="close-dialog icon-btn" data-close-detail aria-label="Tutup detail mobil">${icon('close', 22)}</button><div data-detail-content></div></dialog><div class="toast" role="status" data-toast hidden><span></span><button class="icon-btn" data-close-toast aria-label="Tutup notifikasi">${icon('close', 17)}</button></div>${preview ? `<dialog class="admin-preview-dialog" data-admin-dialog aria-labelledby="admin-preview-title"><button class="close-dialog icon-btn" data-close-admin aria-label="Tutup pratinjau admin">${icon('close', 22)}</button><h2 id="admin-preview-title">Admin showroom</h2><p>Ini pratinjau desain katalog. Pengelolaan stok dan upload foto tersedia melalui aplikasi backend setelah website dipublikasikan.</p><div class="admin-preview-example"><span>Tambah mobil</span><strong>Foto unit</strong><div class="preview-upload">${icon('photo', 30)} Pilih foto mobil</div><label>Model / tipe<input value="Contoh: Avanza 1.5 G" disabled></label><button class="btn primary" disabled>Simpan mobil</button></div></dialog>` : ''}`;
}
